4	    handle,
5	  }: {
6	    did: string;
7	    handle: string;
8	  } = $props();
9	
10	  // Derive a stable hue (0-359) from the DID string using a simple polynomial hash.
11	  // The same DID always produces the same hue across re-renders and app sessions.
12	  let hue = $derived.by(() => {
13	    let h = 0;
14	    for (let i = 0; i < did.length; i++) {
15	      h = (h * 31 + did.charCodeAt(i)) & 0xffffff;
16	    }
17	    return h % 360;
18	  });
19	
20	  // Show '?' for the ATProto sentinel value that means "no handle registered".
21	  let initial = $derived(
22	    handle === 'handle.invalid' ? '?' : handle.charAt(0).toUpperCase()
23	  );
24	</script>
25	
26	<div
27	  class="avatar"
28	  style="background: hsl({hue}, 65%, 45%)"
