input.content:
/*
 * Base layer — global element defaults built on the tokens.
 * Imported once in the root layout, after tokens + fonts.
 */
*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  color-scheme: light; /* the app is light & humane by design — not Ledger-dark */
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--color-bg);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  font-weight: var(--weight-regular);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

a {
  color: var(--color-accent);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}

/* AAA focus: a visible aubergine ring on every interactive element, never removed. */
:where(a, button, input, select, textarea, summary, [role='button'], [tabindex]):focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

::selection {
  background: var(--color-seal-pale);
  color: var(--color-ink);
}

/* Reduced motion is not optional. Collapse animation/transition to near-instant. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

