content.content:
1	<script lang="ts">
2	  import { onMount, onDestroy } from 'svelte';
3	  import { listen, type UnlistenFn } from '@tauri-apps/api/event';
4	  import { listIdentities, getStoredDidDoc, getDeviceKeyId, checkIdentityStatus, type UnauthorizedChange, type IdentityStatus } from '$lib/ipc';
5	  import { extractPdsFromPlcDoc, extractHandle, truncateDid } from '$lib/did-doc-utils';
6	  import DIDAvatar from './DIDAvatar.svelte';
7	
8	  let {
9	    onadd,
10	    onselect,
11	    onalert,
12	  }: {
13	    onadd: () => void;
14	    onselect: (did: string, didDoc: Record<string, unknown>) => void;
15	    onalert?: (did: string, changes: UnauthorizedChange[]) => void;
16	  } = $props();
17	
18	  interface IdentityCard {
19	    did: string;
20	    handle: string | null;
21	    pdsUrl: string | null;
22	    deviceKeyIsRoot: boolean | null;
23	  }
24	
25	  let identities = $state<IdentityCard[]>([]);
26	  let didDocs = $state<Map<string, Record<string, unknown>>>(new Map());
27	  let loading = $state(true);
28	  let loadError = $state<string | null>(null);
29	  let alertData = $state<Map<string, UnauthorizedChange[]>>(new Map());
30	  let unlisten: UnlistenFn | null = null;
31	
32	  function isDeviceKeyRoot(
33	    didDoc: Record<string, unknown>,
34	    deviceKeyId: string
35	  ): boolean | null {
36	    const rotationKeys = didDoc.rotationKeys;
37	    if (!Array.isArray(rotationKeys) || rotationKeys.length === 0) return null;
38	    return rotationKeys[0] === deviceKeyId;
39	  }
40	
41	  async function loadData() {
42	    loading = true;
43	    loadError = null;
44	    try {
45	      const dids = await listIdentities();
46	      identities = [];
47	      didDocs.clear();
48	
49	      for (const did of dids) {
50	        try {
51	          const [docResult, keyIdResult] = await Promise.all([
52	            getStoredDidDoc(did),
53	            getDeviceKeyId(did),
54	          ]);
55	
56	          const handle = docResult ? extractHandle(docResult) : null;
57	          const pdsUrl = docResult ? extractPdsFromPlcDoc(docResult) : null;
58	          const deviceKeyIsRoot = docResult ? isDeviceKeyRoot(docResult, keyIdResult) : null;
59	
60	          if (docResult) {
61	            didDocs.set(did, docResult);
62	          }
63	
64	          identities.push({
65	            did,
66	            handle,
67	            pdsUrl,
68	            deviceKeyIsRoot,
69	          });
70	        } catch (e) {
71	          console.error(`Failed to load identity ${did}:`, e);
72	          // Show degraded card instead of silently dropping the identity
73	          identities.push({
74	            did,
75	            handle: null,
76	            pdsUrl: null,
77	            deviceKeyIsRoot: null,
78	          });
79	        }
80	      }
81	    } catch (e) {
82	      console.error('Failed to load identities:', e);
83	      identities = [];
84	      didDocs.clear();
85	      loadError = 'Failed to load identities. Tap refresh to try again.';
86	    } finally {
87	      loading = false;
88	    }
89	  }
90	
91	  onMount(async () => {
92	    loadData();
93	
94	    // Fetch initial alert status
95	    checkIdentityStatus()
96	      .then((statuses) => {
97	        const data = new Map<string, UnauthorizedChange[]>();
98	        for (const s of statuses) {
99	          if (s.unauthorizedChanges.length > 0) data.set(s.did, s.unauthorizedChanges);
100	        }
101	        alertData = data;
102	      })
103	      .catch((e) => console.warn('Alert check failed:', e));
104	
105	    // Listen for plc_alert events from background monitoring timer
106	    unlisten = await listen<IdentityStatus[]>('plc_alert', (event) => {
107	      if (!Array.isArray(event.payload)) return;
108	      const data = new Map<string, UnauthorizedChange[]>();
109	      for (const s of event.payload) {
110	        if (s.unauthorizedChanges.length > 0) data.set(s.did, s.unauthorizedChanges);
111	      }
112	      alertData = data;
113	    });
114	  });
115	
116	  onDestroy(() => {
117	    unlisten?.();
118	  });
119	
120	  function getBadgeLabel(deviceKeyIsRoot: boolean | null): string {
121	    if (deviceKeyIsRoot === true) {
122	      return 'Root Key';
123	    } else if (deviceKeyIsRoot === false) {
124	      return 'Not Root';
125	    }
126	    return 'Unknown';
127	  }
128	</script>
129	
130	{#if loading}
131	  <div class="screen screen--center">
132	    <div class="spinner" aria-label="Loading"></div>
133	    <p class="status-text">Loading…</p>
134	  </div>
135	{:else}
136	  <div class="screen">
137	    <div class="header">
138	      <h1 class="title">Identity Wallet</h1>
139	      <button class="refresh-btn" onclick={loadData} aria-label="Refresh">↻</button>
140	    </div>
141	
142	    {#if loadError}
143	      <div class="empty-state">
144	        <p class="error-text">{loadError}</p>
145	        <button class="add-btn" onclick={loadData}>Refresh</button>
146	      </div>
147	    {:else if identities.length === 0}
148	      <div class="empty-state">
149	        <p class="empty-text">No identities yet</p>
150	        <button class="add-btn" onclick={onadd}>+ Add Identity</button>
151	      </div>
152	    {:else}
153	      <div class="identity-cards">
154	        {#each identities as card (card.did)}
155	          {@const alerts = alertData.get(card.did)}
156	          <button
157	            class="identity-card"
158	            onclick={() => onselect(card.did, didDocs.get(card.did) ?? {})}
159	          >
160	            <div class="card-content">
161	              <DIDAvatar did={card.did} handle={card.handle ?? 'Unknown'} />
162	              <div class="identity-info">
163	                <p class="handle">@{card.handle ?? 'Unknown handle'}</p>
164	                <p class="did">{truncateDid(card.did)}</p>
165	                {#if card.pdsUrl}
166	                  <p class="pds">{card.pdsUrl}</p>
167	                {/if}
168	              </div>
169	            </div>
170	            <div class="card-badge">
171	              {#if alerts?.length}
172	                <div
173	                  class="badge badge--alert"
174	                  role="button"
175	                  tabindex="0"
176	                  onkeydown={(e) => { if (e.key === 'Enter') { e.stopPropagation(); onalert?.(card.did, alerts ?? []); } }}
177	                  onclick={(e) => { e.stopPropagation(); onalert?.(card.did, alerts ?? []); }}
178	                >
179	                  <span class="badge-dot"></span>
180	                  {alerts?.length} {alerts?.length === 1 ? 'Alert' : 'Alerts'}
181	                </div>
182	              {/if}
183	              <span
184	                class="badge"
