2	  import { onMount } from 'svelte';
3	  import { loadHomeData, logOut, type HomeData } from '$lib/ipc';
4	  import DIDAvatar from './DIDAvatar.svelte';
5	
6	  let {
7	    onnavdiddoc,
8	    onnavrecovery,
9	    onlogout,
10	  }: {
11	    onnavdiddoc: (data: HomeData) => void;
12	    onnavrecovery: (data: HomeData) => void;
13	    onlogout: () => void;
14	  } = $props();
15	
16	  let homeData = $state<HomeData | null>(null);
17	  let loading = $state(true);
18	  let didCopied = $state(false);
19	  let didCopyFailed = $state(false);
20	
21	  async function loadData() {
22	    loading = true;
23	    try {
24	      homeData = await loadHomeData();
25	    } catch {
26	      homeData = null;
27	    } finally {
28	      loading = false;
29	    }
30	  }
31	
32	  onMount(() => {
33	    loadData();
34	  });
35	
36	  // Truncate the DID for display on narrow mobile screens.
37	  // "did:plc:REDACTED" → "did:plc:abcdefgh…uvwxyz"
38	  let displayDid = $derived.by(() => {
39	    const did = homeData?.session?.did ?? '';
40	    const prefix = 'did:plc:';
41	    if (!did.startsWith(prefix)) return did;
42	    const specific = did.slice(prefix.length);
43	    if (specific.length < 14) return did;
44	    return `${prefix}${specific.slice(0, 8)}…${specific.slice(-6)}`;
45	  });
46	
47	  async function copyDid() {
48	    const did = homeData?.session?.did;
49	    if (!did) return;
50	    try {
51	      await navigator.clipboard.writeText(did);
52	      didCopied = true;
53	      setTimeout(() => { didCopied = false; }, 2000);
54	    } catch {
55	      didCopyFailed = true;
56	      setTimeout(() => { didCopyFailed = false; }, 2000);
57	    }
58	  }
59	
60	  async function handleLogOut() {
61	    try {
62	      await logOut();
63	    } catch {
64	      // logOut always succeeds on the Rust side; navigate away even if IPC fails
65	    }
66	    onlogout();
67	  }
68	</script>
