12	  import DIDCeremonyScreen from '$lib/components/onboarding/DIDCeremonyScreen.svelte';
13	  import DIDSuccessScreen from '$lib/components/onboarding/DIDSuccessScreen.svelte';
14	  import ShamirBackupScreen from '$lib/components/onboarding/ShamirBackupScreen.svelte';
15	  import HandleRegistrationScreen from '$lib/components/onboarding/HandleRegistrationScreen.svelte';
16	  import AuthenticatingScreen from '$lib/components/onboarding/AuthenticatingScreen.svelte';
17	  import IdentityInputScreen from '$lib/components/onboarding/IdentityInputScreen.svelte';
18	  import PdsAuthScreen from '$lib/components/onboarding/PdsAuthScreen.svelte';
19	  import EmailVerificationScreen from '$lib/components/onboarding/EmailVerificationScreen.svelte';
20	  import ReviewOperationScreen from '$lib/components/onboarding/ReviewOperationScreen.svelte';
21	  import ClaimSuccessScreen from '$lib/components/onboarding/ClaimSuccessScreen.svelte';
22	  import DIDDocumentScreen from '$lib/components/home/DIDDocumentScreen.svelte';
23	  import RecoveryInfoScreen from '$lib/components/home/RecoveryInfoScreen.svelte';
24	  import AlertDetailScreen from '$lib/components/home/AlertDetailScreen.svelte';
25	  import RecoveryOverrideScreen from '$lib/components/home/RecoveryOverrideScreen.svelte';
26	  import { createAccount, listIdentities, checkIdentityStatus, type CreateAccountError, type OAuthError, type HomeData, type IdentityInfo, type VerifiedClaimOp, type ClaimResult, type UnauthorizedChange } from '$lib/ipc';
27	  import { normalizePlcDocToW3c } from '$lib/did-doc-utils';
28	  import IdentityListHome from '$lib/components/home/IdentityListHome.svelte';
29	
30	  // ── Onboarding step type ─────────────────────────────────────────────────
31	  //
32	  // Design plan originally specified an 'error' state for displaying errors,
33	  // but the implementation uses per-screen error rewinding instead.
34	  // When an error occurs (e.g., EXPIRED_CODE, EMAIL_TAKEN), the app rewinds
35	  // to the relevant screen and displays an inline error message below the
36	  // input field, rather than showing a separate error screen. This is a better
37	  // UX pattern — users can immediately correct the issue on the same screen
38	  // instead of navigating through an extra modal. No 'error' step is needed.
39	
40	  type OnboardingStep =
41	    | 'mode_select'
42	    | 'relay_config'
43	    | 'welcome'
44	    | 'claim_code'
45	    | 'email'
46	    | 'handle'
47	    | 'password'
48	    | 'loading'
49	    | 'did_ceremony'
50	    | 'did_success'
51	    | 'shamir_backup'
52	    | 'handle_registration'
53	    | 'complete'
54	    | 'authenticating'
55	    | 'home'
56	    | 'identity_detail'
57	    | 'did_document'
58	    | 'recovery_info'
59	    | 'alert_detail'
60	    | 'recovery_override'
61	    | 'auth_failed'
62	    | 'identity_input'
63	    | 'pds_auth'
64	    | 'email_verification'
65	    | 'review_operation'
66	    | 'claim_success';
67	
68	  // ── State ────────────────────────────────────────────────────────────────
69	
70	  let step = $state<OnboardingStep>('mode_select');
71	  let form = $state({ claimCode: '', email: '', handle: '', password: '', did: '', share3: '', registeredHandle: '', handleOrDid: '' });
72	
73	  // ── Import flow state ────────────────────────────────────────────────────────
74	  let identityInfo = $state<IdentityInfo | null>(null);
75	  let verifiedClaim = $state<VerifiedClaimOp | null>(null);
76	  let claimResult = $state<ClaimResult | null>(null);
77	
78	  /**
79	   * Per-field error messages displayed by each screen.
80	   * Cleared when the user navigates forward to the next step.
81	   */
82	  let errors = $state<{ claimCode?: string; email?: string; handle?: string; password?: string }>(
83	    {}
84	  );
85	
86	  let authError = $state<OAuthError | null>(null);
87	
88	  let homeData = $state<HomeData | null>(null);
89	
90	  let selectedDidDoc = $state<Record<string, unknown> | null>(null);
91	
92	  let selectedAlertDid = $state<string | null>(null);
93	  let selectedAlertChanges = $state<UnauthorizedChange[]>([]);
94	
95	  let selectedRecoveryCid = $state<string | null>(null);
96	  let selectedRecoveryCreatedAt = $state<string | null>(null);
97	
98	  // ── Navigation helpers ───────────────────────────────────────────────────
99	
100	  function goTo(next: OnboardingStep) {
101	    errors = {};
102	    step = next;
103	  }
104	
105	  // ── Relay configuration and OAuth event listener ──────────────────────
106	
107	  function handleVisibilityChange() {
108	    if (document.visibilityState === 'visible' && step === 'home') {
109	      checkIdentityStatus().catch((e) => {
110	        console.warn('PLC status check failed:', e);
111	      });
112	    }
113	  }
114	
115	  onMount(async () => {
116	    // If the user has claimed identities, skip to home.
117	    try {
118	      const identities = await listIdentities();
119	      if (identities.length > 0) {
120	        step = 'home';
121	      }
122	    } catch (e) {
123	      console.error('listIdentities failed on mount:', e);
124	      // First launch (empty Keychain) or Keychain error — continue to mode_select
125	    }
126	
127	    // Legacy users (relay URL configured but no managed-dids) stay at mode_select.
128	    // RelayConfigScreen internally checks for saved relay URL, so the "Create new
129	    // identity" path handles them correctly without additional logic here.
130	
131	    // Listen for auth_ready from relay OAuth (existing onboarding flow).
132	    listen('auth_ready', () => {
133	      goTo('home');
134	    });
135	    // Note: We intentionally don't await listen() or return a cleanup function here.
136	    // Svelte 5's onMount does not await async cleanup return values (it would receive a
137	    // Promise, not the unlisten function). Since +page.svelte is the root page and never
138	    // unmounts during the app lifecycle, the listener persists for the app's lifetime,
139	    // which is the correct behavior.
140	
141	    // PLC monitoring: check on app foreground
142	    document.addEventListener('visibilitychange', handleVisibilityChange);
143	  });
144	
145	  onDestroy(() => {
146	    document.removeEventListener('visibilitychange', handleVisibilityChange);
147	  });
148	
149	  // ── Account creation ─────────────────────────────────────────────────────
150	
151	  async function submitAccount() {
152	    step = 'loading';
153	    errors = {};
154	
155	    try {
156	      const result = await createAccount({
157	        claimCode: form.claimCode,
158	        email: form.email,
159	        handle: form.handle,
160	      });
161	
162	      // Rust guarantees nextStep is 'did_creation' on success; unrecognized
163	      // relay values fail deserialization and surface as CreateAccountError::Unknown.
164	      step = 'did_ceremony';
165	    } catch (raw: unknown) {
166	      // Guard against non-CreateAccountError shapes (e.g. JS runtime errors).
167	      if (
168	        typeof raw === 'object' &&
169	        raw !== null &&
170	        'code' in raw &&
171	        typeof (raw as CreateAccountError).code === 'string'
172	      ) {
173	        handleError(raw as CreateAccountError);
174	      } else {
175	        errors.handle = "Couldn't reach the server. Check your connection.";
176	        step = 'handle';
177	      }
178	    }
179	  }
180	
181	  function handleError(err: CreateAccountError) {
182	    switch (err.code) {
183	      case 'EXPIRED_CODE':
184	        errors.claimCode = 'This claim code has expired. Please request a new one.';
185	        step = 'claim_code';
186	        break;
187	      case 'REDEEMED_CODE':
188	        errors.claimCode = 'This claim code has already been used.';
189	        step = 'claim_code';
190	        break;
191	      case 'EMAIL_TAKEN':
192	        errors.email = 'An account with that email already exists.';
193	        step = 'email';
194	        break;
195	      case 'HANDLE_TAKEN':
196	        errors.handle = 'That handle is taken. Please choose another.';
197	        step = 'handle';
198	        break;
199	      case 'KEYCHAIN_ERROR':
200	        errors.password = "Couldn't save credentials to your device. Try again.";
201	        step = 'password';
202	        break;
203	      case 'NETWORK_ERROR':
204	        errors.password = "Couldn't reach the server. Check your connection.";
205	        step = 'password';
206	        break;
207	      case 'UNKNOWN':
208	      default:
209	        errors.password = 'Something went wrong. Please try again.';
210	        step = 'password';
211	        break;
212	    }
213	  }
214	</script>
