58	/// In-memory store for failed login attempts per identifier, shared across all login endpoints.
59	/// Maps identifier string → timestamps of recent failures.
60	/// `std::sync::Mutex` is used because the critical section never awaits.
61	///
62	/// **Known limitation:** `createSession` keys by DID or handle; `POST /v1/accounts/sessions`
63	/// keys by email. Both share this store, so an attacker gets `RATE_LIMIT_MAX_FAILURES` attempts
64	/// per endpoint independently against the same account. Acceptable for v0.1; a future revision
65	/// should normalise all identifiers to DID before keying.
66	pub type FailedLoginStore = Arc<Mutex<HashMap<String, VecDeque<Instant>>>>;
