68	/// Wraps an `axum::http::HeaderMap` as an OTel text-map [`Extractor`] so that
69	/// the W3C `traceparent` and `tracestate` headers can be read by the global propagator.
70	struct HeaderMapCarrier<'a>(&'a axum::http::HeaderMap);
71	
72	impl Extractor for HeaderMapCarrier<'_> {
73	    fn get(&self, key: &str) -> Option<&str> {
74	        self.0.get(key).and_then(|v| {
75	            v.to_str().map_or_else(
76	                |_| {
77	                    tracing::debug!(
78	                        header = key,
79	                        "trace propagation header contains non-UTF-8 bytes; ignoring"
80	                    );
81	                    None
82	                },
83	                Some,
84	            )
85	        })
86	    }
87	
88	    fn keys(&self) -> Vec<&str> {
89	        self.0.keys().map(|k| k.as_str()).collect()
90	    }
91	}
