93	/// Custom `MakeSpan` for [`TraceLayer`] that:
94	///  1. Creates an `info_span` with standard HTTP attributes pre-declared.
95	///  2. Extracts an incoming W3C `traceparent` header and sets it as the parent context
96	///     on the new span so upstream traces are joined correctly.
97	#[derive(Clone, Default)]
98	struct OtelMakeSpan;
99	
100	impl<B> tower_http::trace::MakeSpan<B> for OtelMakeSpan {
101	    fn make_span(&mut self, request: &Request<B>) -> tracing::Span {
102	        let span = tracing::info_span!(
103	            "HTTP request",
104	            http.method = %request.method(),
105	            http.target = request.uri().path_and_query().map_or("", |pq| pq.as_str()),
106	            http.status_code = tracing::field::Empty,
107	            otel.status_code = tracing::field::Empty,
108	        );
109	
110	        // Inject parent trace context from incoming W3C traceparent/tracestate headers.
111	        // When telemetry is disabled the global propagator is a no-op, so this is free.
112	        let parent_cx = opentelemetry::global::get_text_map_propagator(|p| {
113	            p.extract(&HeaderMapCarrier(request.headers()))
114	        });
115	        span.set_parent(parent_cx);
116	        span
117	    }
118	}
