431	mod header_carrier_tests {
432	    use super::*;
433	    use axum::http::HeaderMap;
434	    use opentelemetry::propagation::Extractor;
435	
436	    #[test]
437	    fn get_returns_ascii_header_value() {
438	        let mut map = HeaderMap::new();
439	        map.insert("traceparent", "00-abc123-def456-01".parse().unwrap());
440	
441	        let carrier = HeaderMapCarrier(&map);
442	        assert_eq!(carrier.get("traceparent"), Some("00-abc123-def456-01"));
443	    }
444	
445	    #[test]
446	    fn get_returns_none_for_absent_header() {
447	        let map = HeaderMap::new();
448	        let carrier = HeaderMapCarrier(&map);
449	        assert_eq!(carrier.get("traceparent"), None);
450	    }
451	
452	    #[test]
453	    fn get_is_case_insensitive_via_header_map() {
454	        let mut map = HeaderMap::new();
455	        // HTTP/2 headers are lower-case; HeaderMap normalises on insert.
456	        map.insert("tracestate", "vendor=value".parse().unwrap());
457	
458	        let carrier = HeaderMapCarrier(&map);
459	        // HeaderMap normalises to lower-case, so look-up is case-insensitive.
460	        assert_eq!(carrier.get("tracestate"), Some("vendor=value"));
461	    }
462	
463	    #[test]
464	    fn keys_returns_all_header_names() {
465	        let mut map = HeaderMap::new();
466	        map.insert("traceparent", "value1".parse().unwrap());
467	        map.insert("tracestate", "value2".parse().unwrap());
468	
469	        let carrier = HeaderMapCarrier(&map);
470	        let keys = carrier.keys();
471	        assert!(keys.contains(&"traceparent"));
472	        assert!(keys.contains(&"tracestate"));
473	        assert_eq!(keys.len(), 2);
474	    }
475	}
